using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;

BenchmarkRunner.Run<ShapeBench>();

[MemoryDiagnoser]
public class ShapeBench
{
    private Shape _any = new Circle { R = 2 };
    private Circle _circle = new Circle { R = 2 };

    [Benchmark(Baseline = true)]
    public double Virtual() => _any.Area();

    [Benchmark]
    public double Sealed() => _circle.Area();
}

